#!/usr/bin/env node
// THE COMMITTED PALETTE SPEC STILL DESCRIBES THE STYLESHEET THAT SHIPS.
//
// palettes/studio.json is generated by tools/palette-spec.mjs, which needs a
// browser and a served build — so it is committed, like the branch guard's
// hook, and like every committed artefact it can go stale in the tree while
// everything stays green. What that costs specifically: CI's palette gate
// measures the colours in the JSON, the app paints the colours in
// public/palette.css, and the moment those differ the gate is reporting on a
// palette nobody sees. Its own header says the values are generated somewhere
// else and have to be re-run; a sentence saying that has never once refused a
// commit.
//
// This cannot regenerate — no browser here — so it checks the one thing a text
// scan can: the spec records the sha256 of the stylesheet it was built from,
// and that stylesheet is still byte-for-byte what it was.
//
// WHAT IT DOES NOT COVER, said out loud: `_renders` is measured from the whole
// app, not just palette.css, so a change in style.css can add a painted pairing
// this cannot see. That half needs the browser and lives in the a11y walk,
// which re-measures the list and fails on a difference.
import { readFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { join } from "node:path";

const arg = process.argv.find((a) => a.startsWith("--repo="));
const root = arg ? arg.split("=")[1] : ".";
const SPEC = join(root, "palettes/studio.json");

let spec;
try { spec = JSON.parse(readFileSync(SPEC, "utf8")); }
catch (e) { console.log(`FAIL  palettes/studio.json: ${e.message}`); process.exit(1); }

const src = spec._source;
if (!src || !src.file || !src.sha256) {
  console.log("FAIL  palettes/studio.json carries no _source — regenerate with tools/palette-spec.mjs");
  process.exit(1);
}
const now = createHash("sha256").update(readFileSync(join(root, src.file))).digest("hex");
if (now !== src.sha256) {
  console.log(`FAIL  ${src.file} has changed since palettes/studio.json was generated`);
  console.log(`        spec was built from ${src.sha256.slice(0, 12)}, the file is now ${now.slice(0, 12)}`);
  console.log("        serve dist/ and re-run:  node tools/palette-spec.mjs > palettes/studio.json");
  process.exit(1);
}
if (!Array.isArray(spec._renders) || !spec._renders.length) {
  console.log("FAIL  palettes/studio.json has no _renders list — every accent pairing would become a hard floor");
  process.exit(1);
}
console.log(`palette-spec-check: spec matches ${src.file} @ ${now.slice(0, 12)}, ${spec._renders.length} measured pairings`);
process.exit(0);
